js -e <<'EOF'
const tabs = await listTabs();
const page = await connectToPage(tabs.find(t => t.active).id);
const iframe = await page.$('iframe');
const frame = await iframe.contentFrame();

// I'll try to find the button "C" one more time with a slightly different approach
// The snapshot earlier showed a button with text 'C'. Wait, no, it showed "button "C" [ref=e104]".
// Let me try selecting by that specific ref if possible, or search for it again in the iframe.

const buttonC = await frame.$('[aria-label="C"]');
if (buttonC) {
    await buttonC.click();
} else {
    // try to find by innerText
    const buttons = await frame.$$('button');
    for (let b of buttons) {
        const text = await b.evaluate(el => el.innerText.trim());
        if (text === 'C') {
            await b.click();
            break;
        }
    }
}
// Submit
const submit = await frame.evaluateHandle(() => {
    return Array.from(document.querySelectorAll('button')).find(b => b.innerText.includes('Submit'));
});
if (submit) await submit.click();
EOF

